"""Red-Black Tree implementation with all standard operations."""

RED = True
BLACK = False


class Node:
    __slots__ = ("key", "color", "left", "right", "parent")

    def __init__(self, key, color=RED):
        self.key = key
        self.color = color
        self.left = None
        self.right = None
        self.parent = None


class RedBlackTree:
    """Red-black tree satisfying:
    1. Every node is red or black.
    2. The root is black.
    3. Every leaf (None) is black.
    4. A red node has only black children.
    5. Every path from a node to its leaves has the same black-height.
    """

    def __init__(self):
        self.root = None

    # ── Rotations ────────────────────────────────────────────────────

    def _left_rotate(self, x):
        y = x.right
        x.right = y.left
        if y.left is not None:
            y.left.parent = x
        y.parent = x.parent
        if x.parent is None:
            self.root = y
        elif x is x.parent.left:
            x.parent.left = y
        else:
            x.parent.right = y
        y.left = x
        x.parent = y

    def _right_rotate(self, y):
        x = y.left
        y.left = x.right
        if x.right is not None:
            x.right.parent = y
        x.parent = y.parent
        if y.parent is None:
            self.root = x
        elif y is y.parent.left:
            y.parent.left = x
        else:
            y.parent.right = x
        x.right = y
        y.parent = x

    # ── Insert ───────────────────────────────────────────────────────

    def insert(self, key):
        node = Node(key)
        parent = None
        current = self.root
        while current is not None:
            parent = current
            if node.key < current.key:
                current = current.left
            elif node.key > current.key:
                current = current.right
            else:
                return  # duplicate keys not inserted
        node.parent = parent
        if parent is None:
            self.root = node
        elif node.key < parent.key:
            parent.left = node
        else:
            parent.right = node
        self._insert_fixup(node)

    def _insert_fixup(self, z):
        while z.parent is not None and z.parent.color == RED:
            if z.parent is z.parent.parent.left:
                y = z.parent.parent.right  # uncle
                if y is not None and y.color == RED:
                    z.parent.color = BLACK
                    y.color = BLACK
                    z.parent.parent.color = RED
                    z = z.parent.parent
                else:
                    if z is z.parent.right:
                        z = z.parent
                        self._left_rotate(z)
                    z.parent.color = BLACK
                    z.parent.parent.color = RED
                    self._right_rotate(z.parent.parent)
            else:
                y = z.parent.parent.left  # uncle
                if y is not None and y.color == RED:
                    z.parent.color = BLACK
                    y.color = BLACK
                    z.parent.parent.color = RED
                    z = z.parent.parent
                else:
                    if z is z.parent.left:
                        z = z.parent
                        self._right_rotate(z)
                    z.parent.color = BLACK
                    z.parent.parent.color = RED
                    self._left_rotate(z.parent.parent)
        self.root.color = BLACK

    # ── Delete ───────────────────────────────────────────────────────

    def delete(self, key):
        z = self._search_node(key)
        if z is None:
            return
        self._delete_node(z)

    def _delete_node(self, z):
        y = z
        y_original_color = y.color
        if z.left is None:
            x = z.right
            self._transplant(z, z.right)
        elif z.right is None:
            x = z.left
            self._transplant(z, z.left)
        else:
            y = self._minimum(z.right)
            y_original_color = y.color
            x = y.right
            if y.parent is z:
                if x is not None:
                    x.parent = y
            else:
                self._transplant(y, y.right)
                y.right = z.right
                y.right.parent = y
            self._transplant(z, y)
            y.left = z.left
            y.left.parent = y
            y.color = z.color
        if y_original_color == BLACK:
            self._delete_fixup(x)

    def _transplant(self, u, v):
        if u.parent is None:
            self.root = v
        elif u is u.parent.left:
            u.parent.left = v
        else:
            u.parent.right = v
        if v is not None:
            v.parent = u.parent

    def _delete_fixup(self, x):
        while x is not self.root and self._is_black(x):
            if x is not None and x is x.parent.left:
                w = x.parent.right
                if w is not None and w.color == RED:
                    w.color = BLACK
                    x.parent.color = RED
                    self._left_rotate(x.parent)
                    w = x.parent.right
                if w is None:
                    x = x.parent
                elif self._is_black(w.left) and self._is_black(w.right):
                    w.color = RED
                    x = x.parent
                else:
                    if self._is_black(w.right):
                        if w.left is not None:
                            w.left.color = BLACK
                        w.color = RED
                        self._right_rotate(w)
                        w = x.parent.right
                    w.color = x.parent.color
                    x.parent.color = BLACK
                    if w.right is not None:
                        w.right.color = BLACK
                    self._left_rotate(x.parent)
                    x = self.root
            elif x is not None:
                w = x.parent.left
                if w is not None and w.color == RED:
                    w.color = BLACK
                    x.parent.color = RED
                    self._right_rotate(x.parent)
                    w = x.parent.left
                if w is None:
                    x = x.parent
                elif self._is_black(w.right) and self._is_black(w.left):
                    w.color = RED
                    x = x.parent
                else:
                    if self._is_black(w.left):
                        if w.right is not None:
                            w.right.color = BLACK
                        w.color = RED
                        self._left_rotate(w)
                        w = x.parent.left
                    w.color = x.parent.color
                    x.parent.color = BLACK
                    if w.left is not None:
                        w.left.color = BLACK
                    self._right_rotate(x.parent)
                    x = self.root
            else:
                x = self.root
        if x is not None:
            x.color = BLACK

    @staticmethod
    def _is_black(node):
        return node is None or node.color == BLACK

    # ── Search ───────────────────────────────────────────────────────

    def search(self, key):
        node = self._search_node(key)
        return node is not None

    def _search_node(self, key):
        current = self.root
        while current is not None:
            if key == current.key:
                return current
            elif key < current.key:
                current = current.left
            else:
                current = current.right
        return None

    # ── Min / Max ────────────────────────────────────────────────────

    def minimum(self):
        if self.root is None:
            return None
        return self._minimum(self.root).key

    def _minimum(self, node):
        while node.left is not None:
            node = node.left
        return node

    def maximum(self):
        if self.root is None:
            return None
        return self._maximum(self.root).key

    def _maximum(self, node):
        while node.right is not None:
            node = node.right
        return node

    # ── Successor / Predecessor ──────────────────────────────────────

    def successor(self, key):
        node = self._search_node(key)
        if node is None:
            return None
        if node.right is not None:
            return self._minimum(node.right).key
        y = node.parent
        while y is not None and node is y.right:
            node = y
            y = y.parent
        return y.key if y is not None else None

    def predecessor(self, key):
        node = self._search_node(key)
        if node is None:
            return None
        if node.left is not None:
            return self._maximum(node.left).key
        y = node.parent
        while y is not None and node is y.left:
            node = y
            y = y.parent
        return y.key if y is not None else None

    # ── Traversal ────────────────────────────────────────────────────

    def inorder(self):
        result = []
        self._inorder(self.root, result)
        return result

    def _inorder(self, node, result):
        if node is not None:
            self._inorder(node.left, result)
            result.append(node.key)
            self._inorder(node.right, result)

    # ── Validation ───────────────────────────────────────────────────

    def is_valid(self):
        """Verify all red-black tree invariants."""
        if self.root is None:
            return True
        if self.root.color != BLACK:
            return False
        return self._check_node(self.root) != -1

    def _check_node(self, node):
        """Return black-height of subtree, or -1 if invariants violated."""
        if node is None:
            return 1
        left_bh = self._check_node(node.left)
        right_bh = self._check_node(node.right)
        if left_bh == -1 or right_bh == -1:
            return -1
        if left_bh != right_bh:
            return -1
        if node.color == RED:
            if (node.left and node.left.color == RED) or (
                node.right and node.right.color == RED
            ):
                return -1
        return left_bh + (1 if node.color == BLACK else 0)

    # ── Utility ──────────────────────────────────────────────────────

    def __len__(self):
        return self._count(self.root)

    def _count(self, node):
        if node is None:
            return 0
        return 1 + self._count(node.left) + self._count(node.right)

    def __contains__(self, key):
        return self.search(key)

    def __repr__(self):
        return f"RedBlackTree({self.inorder()})"


# ── Demo / Smoke test ───────────────────────────────────────────────

if __name__ == "__main__":
    import random

    tree = RedBlackTree()
    values = list(range(1, 21))
    random.shuffle(values)

    for v in values:
        tree.insert(v)
    print(f"Inserted {values}")
    print(f"Inorder:  {tree.inorder()}")
    print(f"Valid:    {tree.is_valid()}")
    print(f"Min:      {tree.minimum()}")
    print(f"Max:      {tree.maximum()}")
    print(f"Size:     {len(tree)}")

    for v in [5, 10, 15, 1, 20]:
        tree.delete(v)
    print(f"\nAfter deleting [5,10,15,1,20]: {tree.inorder()}")
    print(f"Valid: {tree.is_valid()}")
    print(f"Size:  {len(tree)}")

    # Stress test
    tree = RedBlackTree()
    data = random.sample(range(10000), 5000)
    for v in data:
        tree.insert(v)
    random.shuffle(data)
    for v in data[:3000]:
        tree.delete(v)
    assert tree.is_valid(), "Validation failed after stress test!"
    print(f"\nStress test passed — {len(tree)} nodes, valid={tree.is_valid()}")

"""Red-Black Tree with all standard operations.

Properties:
  1. Every node is red or black.
  2. The root is black.
  3. Every leaf (NIL sentinel) is black.
  4. A red node has only black children.
  5. Every path from a node to its descendant leaves has the same black-height.
"""

RED = True
BLACK = False


class Node:
    __slots__ = ("key", "color", "left", "right", "parent")

    def __init__(self, key, color=RED):
        self.key = key
        self.color = color
        self.left = None
        self.right = None
        self.parent = None


class RedBlackTree:
    def __init__(self):
        self.nil = Node(key=None, color=BLACK)
        self.root = self.nil

    # ── Rotations ────────────────────────────────────────────────────

    def _rotate_left(self, x):
        y = x.right
        x.right = y.left
        if y.left is not self.nil:
            y.left.parent = x
        y.parent = x.parent
        if x.parent is None:
            self.root = y
        elif x is x.parent.left:
            x.parent.left = y
        else:
            x.parent.right = y
        y.left = x
        x.parent = y

    def _rotate_right(self, x):
        y = x.left
        x.left = y.right
        if y.right is not self.nil:
            y.right.parent = x
        y.parent = x.parent
        if x.parent is None:
            self.root = y
        elif x is x.parent.right:
            x.parent.right = y
        else:
            x.parent.left = y
        y.right = x
        x.parent = y

    # ── Insert ───────────────────────────────────────────────────────

    def insert(self, key):
        node = Node(key)
        node.left = self.nil
        node.right = self.nil

        parent = None
        current = self.root
        while current is not self.nil:
            parent = current
            current = current.left if key < current.key else current.right

        node.parent = parent
        if parent is None:
            self.root = node
        elif key < parent.key:
            parent.left = node
        else:
            parent.right = node

        self._insert_fixup(node)

    def _insert_fixup(self, node):
        while node.parent and node.parent.color is RED:
            if node.parent is node.parent.parent.left:
                uncle = node.parent.parent.right
                if uncle.color is RED:
                    node.parent.color = BLACK
                    uncle.color = BLACK
                    node.parent.parent.color = RED
                    node = node.parent.parent
                else:
                    if node is node.parent.right:
                        node = node.parent
                        self._rotate_left(node)
                    node.parent.color = BLACK
                    node.parent.parent.color = RED
                    self._rotate_right(node.parent.parent)
            else:
                uncle = node.parent.parent.left
                if uncle.color is RED:
                    node.parent.color = BLACK
                    uncle.color = BLACK
                    node.parent.parent.color = RED
                    node = node.parent.parent
                else:
                    if node is node.parent.left:
                        node = node.parent
                        self._rotate_right(node)
                    node.parent.color = BLACK
                    node.parent.parent.color = RED
                    self._rotate_left(node.parent.parent)
        self.root.color = BLACK

    # ── Delete ───────────────────────────────────────────────────────

    def delete(self, key):
        node = self._search(key)
        if node is self.nil:
            raise KeyError(key)
        self._delete_node(node)

    def _delete_node(self, node):
        original_color = node.color
        if node.left is self.nil:
            replacement = node.right
            self._transplant(node, node.right)
        elif node.right is self.nil:
            replacement = node.left
            self._transplant(node, node.left)
        else:
            successor = self._minimum(node.right)
            original_color = successor.color
            replacement = successor.right
            if successor.parent is node:
                replacement.parent = successor
            else:
                self._transplant(successor, successor.right)
                successor.right = node.right
                successor.right.parent = successor
            self._transplant(node, successor)
            successor.left = node.left
            successor.left.parent = successor
            successor.color = node.color

        if original_color is BLACK:
            self._delete_fixup(replacement)

    def _transplant(self, u, v):
        if u.parent is None:
            self.root = v
        elif u is u.parent.left:
            u.parent.left = v
        else:
            u.parent.right = v
        v.parent = u.parent

    def _delete_fixup(self, node):
        while node is not self.root and node.color is BLACK:
            if node is node.parent.left:
                sibling = node.parent.right
                if sibling.color is RED:
                    sibling.color = BLACK
                    node.parent.color = RED
                    self._rotate_left(node.parent)
                    sibling = node.parent.right
                if sibling.left.color is BLACK and sibling.right.color is BLACK:
                    sibling.color = RED
                    node = node.parent
                else:
                    if sibling.right.color is BLACK:
                        sibling.left.color = BLACK
                        sibling.color = RED
                        self._rotate_right(sibling)
                        sibling = node.parent.right
                    sibling.color = node.parent.color
                    node.parent.color = BLACK
                    sibling.right.color = BLACK
                    self._rotate_left(node.parent)
                    node = self.root
            else:
                sibling = node.parent.left
                if sibling.color is RED:
                    sibling.color = BLACK
                    node.parent.color = RED
                    self._rotate_right(node.parent)
                    sibling = node.parent.left
                if sibling.right.color is BLACK and sibling.left.color is BLACK:
                    sibling.color = RED
                    node = node.parent
                else:
                    if sibling.left.color is BLACK:
                        sibling.right.color = BLACK
                        sibling.color = RED
                        self._rotate_left(sibling)
                        sibling = node.parent.left
                    sibling.color = node.parent.color
                    node.parent.color = BLACK
                    sibling.left.color = BLACK
                    self._rotate_right(node.parent)
                    node = self.root
        node.color = BLACK

    # ── Search ───────────────────────────────────────────────────────

    def search(self, key):
        return self._search(key) is not self.nil

    def _search(self, key):
        current = self.root
        while current is not self.nil:
            if key == current.key:
                return current
            current = current.left if key < current.key else current.right
        return self.nil

    # ── Minimum / Maximum ────────────────────────────────────────────

    def minimum(self):
        if self.root is self.nil:
            return None
        return self._minimum(self.root).key

    def _minimum(self, node):
        while node.left is not self.nil:
            node = node.left
        return node

    def maximum(self):
        if self.root is self.nil:
            return None
        return self._maximum(self.root).key

    def _maximum(self, node):
        while node.right is not self.nil:
            node = node.right
        return node

    # ── Successor / Predecessor ──────────────────────────────────────

    def successor(self, key):
        node = self._search(key)
        if node is self.nil:
            return None
        if node.right is not self.nil:
            return self._minimum(node.right).key
        parent = node.parent
        while parent is not None and node is parent.right:
            node = parent
            parent = parent.parent
        return parent.key if parent is not None else None

    def predecessor(self, key):
        node = self._search(key)
        if node is self.nil:
            return None
        if node.left is not self.nil:
            return self._maximum(node.left).key
        parent = node.parent
        while parent is not None and node is parent.left:
            node = parent
            parent = parent.parent
        return parent.key if parent is not None else None

    # ── Floor / Ceiling ──────────────────────────────────────────────

    def floor(self, key):
        """Largest key <= key, or None."""
        result = None
        node = self.root
        while node is not self.nil:
            if node.key == key:
                return key
            elif node.key < key:
                result = node.key
                node = node.right
            else:
                node = node.left
        return result

    def ceiling(self, key):
        """Smallest key >= key, or None."""
        result = None
        node = self.root
        while node is not self.nil:
            if node.key == key:
                return key
            elif node.key > key:
                result = node.key
                node = node.left
            else:
                node = node.right
        return result

    # ── Rank / Select ────────────────────────────────────────────────

    def rank(self, key):
        """Number of keys strictly less than key."""
        count = 0
        node = self.root
        while node is not self.nil:
            if key < node.key:
                node = node.left
            elif key > node.key:
                count += 1 + self._count(node.left)
                node = node.right
            else:
                return count + self._count(node.left)
        return count

    def select(self, k):
        """k-th smallest key (0-indexed), or None if out of range."""
        node = self.root
        while node is not self.nil:
            left_size = self._count(node.left)
            if k < left_size:
                node = node.left
            elif k > left_size:
                k -= left_size + 1
                node = node.right
            else:
                return node.key
        return None

    # ── Range query ──────────────────────────────────────────────────

    def range_query(self, lo, hi):
        """Return all keys in [lo, hi]."""
        result = []
        self._range_query(self.root, lo, hi, result)
        return result

    def _range_query(self, node, lo, hi, result):
        if node is self.nil:
            return
        if lo < node.key:
            self._range_query(node.left, lo, hi, result)
        if lo <= node.key <= hi:
            result.append(node.key)
        if hi > node.key:
            self._range_query(node.right, lo, hi, result)

    # ── Traversal ────────────────────────────────────────────────────

    def inorder(self):
        result = []
        self._inorder(self.root, result)
        return result

    def _inorder(self, node, result):
        if node is not self.nil:
            self._inorder(node.left, result)
            result.append(node.key)
            self._inorder(node.right, result)

    # ── Validation ───────────────────────────────────────────────────

    def is_valid(self):
        """Verify all five red-black tree invariants."""
        if self.root is self.nil:
            return True
        if self.root.color is not BLACK:
            return False
        return self._check_invariants(self.root) != -1

    def _check_invariants(self, node):
        """Return black-height of subtree, or -1 if any invariant is violated."""
        if node is self.nil:
            return 1
        left_bh = self._check_invariants(node.left)
        right_bh = self._check_invariants(node.right)
        if left_bh == -1 or right_bh == -1 or left_bh != right_bh:
            return -1
        if node.color is RED:
            if node.left.color is RED or node.right.color is RED:
                return -1
        return left_bh + (1 if node.color is BLACK else 0)

    # ── Size / Containment ───────────────────────────────────────────

    def __len__(self):
        return self._count(self.root)

    def _count(self, node):
        if node is self.nil:
            return 0
        return 1 + self._count(node.left) + self._count(node.right)

    def __contains__(self, key):
        return self.search(key)

    def __repr__(self):
        return f"RedBlackTree({self.inorder()})"


# ── Demo ─────────────────────────────────────────────────────────────

if __name__ == "__main__":
    import random

    tree = RedBlackTree()
    values = list(range(1, 21))
    random.shuffle(values)

    for v in values:
        tree.insert(v)
    print(f"Inserted {values}")
    print(f"Inorder:     {tree.inorder()}")
    print(f"Valid:       {tree.is_valid()}")
    print(f"Min / Max:   {tree.minimum()} / {tree.maximum()}")
    print(f"Size:        {len(tree)}")
    print(f"Floor(9.5):  {tree.floor(9.5)}")
    print(f"Ceiling(9.5):{tree.ceiling(9.5)}")
    print(f"Rank(10):    {tree.rank(10)}")
    print(f"Select(4):   {tree.select(4)}")
    print(f"Range[5,10]: {tree.range_query(5, 10)}")
    print(f"Successor(7):{tree.successor(7)}")
    print(f"Predecessor(7):{tree.predecessor(7)}")

    for v in [5, 10, 15, 1, 20]:
        tree.delete(v)
    print(f"\nAfter deleting [5,10,15,1,20]: {tree.inorder()}")
    print(f"Valid: {tree.is_valid()}, Size: {len(tree)}")

    # Stress test: insert, delete, validate
    tree = RedBlackTree()
    data = random.sample(range(10000), 5000)
    for v in data:
        tree.insert(v)
    assert tree.is_valid(), "Failed after inserts"

    random.shuffle(data)
    for v in data[:3000]:
        tree.delete(v)
    assert tree.is_valid(), "Failed after deletes"
    print(f"\nStress test passed — {len(tree)} nodes, valid={tree.is_valid()}")
